                phone={userSettings.Phone}
                hasReset={!!userSettings.Phone.Reset}
                disableVerifyCta
                inputProps={{ label: c('Safety review').t`Recovery phone number` }}
                renderForm={({ onSubmit, input, submitButtonProps }) => {
                    return (
