import type { Ref } from 'react';
import { useRef, useState } from 'react';
import { AutoSizer, CellMeasurer, CellMeasurerCache, List } from 'react-virtualized';

import { c } from 'ttag';

import { Input } from '@proton/atoms';
import Dropdown from '@proton/components/components/dropdown/Dropdown';
import DropdownButton from '@proton/components/components/dropdown/DropdownButton';
import Icon from '@proton/components/components/icon/Icon';
import { normalize } from '@proton/shared/lib/helpers/string';
import generateUID from '@proton/utils/generateUID';

import CountrySelectRow from './PhoneCountrySelectRow';
import type { CountryOptionData } from './helper';

interface Props {
    options: CountryOptionData[];
    value?: CountryOptionData;
    embedded?: boolean;
    onChange: (newValue: CountryOptionData) => void;
    onClosed?: (isFromSelection: boolean) => void;
}

const cache = new CellMeasurerCache({
    defaultHeight: 100,
    fixedWidth: true,
    keyMapper: () => 0,
});

const CountrySelect = ({ value, options, onChange, embedded, onClosed }: Props) => {
    const anchorRef = useRef<HTMLButtonElement>(null);
    const [isOpen, setIsOpen] = useState(false);
    const [search, setSearch] = useState('');
    const normalizedSearch = normalize(search, true);
    const filteredOptions = options.filter(({ countryName }) => {
        return normalize(countryName, true).includes(normalizedSearch);
    });

    const selectedIndex = !value ? 0 : filteredOptions.indexOf(value);

    const pickRef = useRef(false);

    const handleChange = (value: CountryOptionData) => {
        onChange(value);
        setIsOpen(false);
        pickRef.current = true;
    };

    const uid = generateUID('phone-number-prefix');

    return (
        <>
            <span className="sr-only" id={uid}>{c('Info').t`Country code`}</span>
            <DropdownButton
                as="button"
                type="button"
                isOpen={isOpen}
                hasCaret
                onClick={() => {
                    pickRef.current = false;
                    setIsOpen(!isOpen);
                }}
                className="unstyled self-stretch my-1 pr-2 border-right"
                ref={anchorRef}
                caretClassName="my-auto"
                aria-live="assertive"
                aria-atomic="true"
                aria-label={value?.countryName}
                aria-describedby={uid}
            >
                <span className="flex mr-2">
                    {!value ? (
                        <Icon name="globe" className="align-middle inline-flex" />
                    ) : (
                        <img
                            role="presentation"
                            alt={value.countryName}
                            src={value.countryFlag}
                            width="30"
                            height="30"
                            className="align-middle inline-flex"
                        />
                    )}
                </span>
                <span className="min-w-custom inline-flex" style={{ '--min-w-custom': '3em' }} dir="ltr">
                    +{value ? value.countryCallingCode : '00'}
                </span>
            </DropdownButton>

            <Dropdown
                isOpen={isOpen}
                anchorRef={anchorRef}
                onClose={() => {
                    pickRef.current = false;
                    setIsOpen(false);
                }}
                onClosed={() => {
                    setSearch('');
                    onClosed?.(pickRef.current);
                }}
                offset={4}
                autoClose={false}
                noCaret
                disableDefaultArrowNavigation
                onKeyDown={(e) => {
                    const { key } = e;
                    switch (key) {
                        case 'Enter': {
                            e.preventDefault();
                            pickRef.current = true;
                            setIsOpen(false);
                            break;
                        }
                        case 'ArrowUp': {
                            e.preventDefault();
                            const newIndex = selectedIndex - 1;
                            const newValue = filteredOptions[Math.max(newIndex, 0)];
                            if (newValue) {
                                onChange(newValue);
                            }
                            break;
                        }
                        case 'ArrowDown': {
                            e.preventDefault();
                            const newIndex = selectedIndex + 1;
                            const newValue = filteredOptions[Math.min(newIndex, filteredOptions.length - 1)];
                            if (newValue) {
                                onChange(newValue);
                            }
                            break;
                        }
                        default:
                            break;
                    }
                }}
            >
                <form name="search" className="p-4">
                    <Input
                        id="search-keyword"
                        value={search}
                        onValue={setSearch}
                        autoFocus={!embedded}
                        placeholder="Country"
                        prefix={<Icon name="magnifier" alt={c('Action').t`Search countries`} />}
                    />
                </form>

                <div className="h-custom min-w-custom" style={{ '--h-custom': '20em', '--min-w-custom': '18em' }}>
                    {!filteredOptions.length ? (
                        <div className="pl-4" role="alert">{c('Info').t`No results found`}</div>
                    ) : (
                        <AutoSizer>
                            {({ height, width }) => (
                                <List
                                    height={height}
                                    width={width}
                                    rowHeight={cache.rowHeight}
                                    className="unstyled m-0 p-0 overflow-auto"
                                    scrollToIndex={selectedIndex < 0 ? 0 : selectedIndex}
                                    rowCount={filteredOptions.length}
                                    rowRenderer={({ index, key, parent, style }) => {
                                        return (
                                            <CellMeasurer
                                                cache={cache}
                                                columnIndex={0}
                                                key={key}
                                                rowIndex={index}
                                                parent={parent}
                                            >
                                                {({ registerChild }) => (
                                                    <CountrySelectRow
                                                        ref={registerChild as Ref<HTMLDivElement>}
                                                        data={filteredOptions[index]}
                                                        value={value}
                                                        key={key}
                                                        style={style}
                                                        onChange={handleChange}
                                                    />
                                                )}
                                            </CellMeasurer>
                                        );
                                    }}
                                />
                            )}
                        </AutoSizer>
                    )}
                </div>
            </Dropdown>
        </>
    );
};

export default CountrySelect;
import examples from 'libphonenumber-js/examples.mobile.json';
import metadata from 'libphonenumber-js/metadata.min.json';
import type { CountryCode } from 'libphonenumber-js/min';
import parsePhoneNumberFromString, {
    AsYouType,
    formatIncompletePhoneNumber,
    getCountryCallingCode,
    getExampleNumber,
} from 'libphonenumber-js/min';

import isTruthy from '@proton/utils/isTruthy';

import { callingCodeToLeading, getCountryMap } from './data';
import { getFlagSvg } from './flagSvgs';

export const getTrimmedString = (string: string) => {
    // Handle (123) -> (123
    const slicedValue = string.match(/\([\d]+$/) ? string.slice(0, -1) : string;
    // Remove everything except numbers and +
    const trimmedString = slicedValue.replace(/[^0-9+]+/g, '');
    if (!trimmedString.length) {
        return '';
    }
    // Remove all + in case there are multiple
    return trimmedString[0] + trimmedString.slice(1).replace(/\+/g, '');
};

export const getSafeCountryCallingCode = (country: string) => {
    try {
        return getCountryCallingCode(country as CountryCode) as string;
    } catch (e: any) {
        return '';
    }
};

export const getCountryFromCallingCode = (callingCode: string) => {
    const countries = metadata.country_calling_codes[callingCode];
    if (!countries || countries.length === 0) {
        return;
    }
    if (countries.length === 1) {
        return countries[0];
    }
    return countries[0];
};

export const getNumberWithCountryCode = (value: string, countryCallingCode: string) => {
    if (value.includes('+')) {
        return value;
    }
    if (!countryCallingCode) {
        return value;
    }
    return `+${countryCallingCode}${value}`;
};

export const getExamplePlaceholder = (country: string) => {
    const example = getExampleNumber(country as CountryCode, examples);
    if (!example) {
        return '';
    }
    return example.formatInternational();
};

export const getNumberWithoutCountryCode = (value: string, countryCallingCode: string) => {
    return value.replace(`+${countryCallingCode}`, '').trim();
};

export const getCountryFromNumber = (value: string) => {
    const asYouType = new AsYouType();
    asYouType.input(value);
    const result = asYouType.getNumber();
    if (result) {
        return result.country || getCountryFromCallingCode(result.countryCallingCode as string) || '';
    }
    const country = asYouType.getCountry();
    if (country) {
        return country;
    }
    const callingCode = asYouType.getCallingCode();
    if (callingCode) {
        const country = getCountryFromCallingCode(callingCode);
        if (country) {
            return country;
        }
    }
    if (!value.length) {
        return '';
    }
    if (value[0] === '+') {
        const callingCode = value.slice(1);
        const country = getCountryFromCallingCode(callingCode);
        if (country) {
            return country;
        }
    }
    return '';
};

export interface CountryOptionData {
    countryCode: string;
    countryName: string;
    countryCallingCode: string;
    countryFlag: string;
}

export const getCountries = (): CountryOptionData[] => {
    const countryMap = getCountryMap();
    return Object.keys(metadata.countries)
        .map((countryCode): CountryOptionData | undefined => {
            const countryCallingCode = getSafeCountryCallingCode(countryCode as CountryCode);
            const countryName = countryMap[countryCode];
            const countryFlag = getFlagSvg(countryCode);
            if (!countryFlag || !countryName || !countryCallingCode) {
                return;
            }
            return {
                countryCode,
                countryName,
                countryCallingCode,
                countryFlag,
            };
        })
        .filter(isTruthy)
        .sort((a, b) => a.countryName.localeCompare(b.countryName));
};

export const getCursorPosition = (digitIndex: number, value: string) => {
    const regex = /[\d+]/;

    let n = 0;
    let i = 0;

    for (; i < value.length; ++i) {
        if (value[i].match(regex)) {
            if (n++ >= digitIndex) {
                break;
            }
        }
    }

    if (!value[i - 1]?.match(regex)) {
        i -= 1;
    }

    return Math.max(0, Math.min(i, value.length));
};

export const getFormattedValue = (number: string) => {
    const result = parsePhoneNumberFromString(number);
    if (result && result.isValid()) {
        return result.formatInternational();
    }
    return formatIncompletePhoneNumber(number);
};

export const getSpecificCountry = (
    value: string,
    countryCallingCode: string,
    countryCode: string
): [string, number] => {
    const leadings = callingCodeToLeading[countryCallingCode];
    if (!leadings) {
        return [countryCode, 0];
    }
    return leadings.reduce(
        (acc, { countryCode, areaCodes }) => {
            const result = areaCodes.find((areaCode) => value.startsWith(areaCode));
            if (result && result.length >= acc[1]) {
                return [countryCode, result.length];
            }
            return acc;
        },
        [countryCode, 0]
    );
};

export const getSpecificMaxLength = (countryCallingCode: string, countryCode: string) => {
    const leadings = callingCodeToLeading[countryCallingCode] || [];
    const areaCodes =
        leadings.find((leading) => {
            return countryCode === leading.countryCode;
        })?.areaCodes || [];
    return areaCodes.reduce((acc, cur) => {
        return Math.max(acc, cur.length);
    }, 0);
};

